import { GoogleGenerativeAI } from '@google/generative-ai';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Initialize the Google Gen AI client
const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY);

async function generatePaper() {
  const model = genAI.getGenerativeModel({ model: "gemini-pro" });

  const prompt = "You are a distinguished computer science researcher specializing in version control systems, distributed graphs, and AI-native infrastructure. Write a highly detailed, academic-style whitepaper (approximately 2,000 words) titled 'The Mathematics of Intent: Hashing Semantic Logic for AI-Native Version Control'. The paper must rigorously explain why legacy Git (line-diffing) is fundamentally broken in the era of autonomous coding agents (like Cursor, Aider, SWE-agent), and how Aura solves this using Abstract Syntax Tree (AST) hashing. The paper should be divided into sections: 1. Abstract, 2. Introduction, 3. The Merkle-Graph Architecture, 4. Blast Radius Validation, 5. Neural Intent RAG, 6. Autonomous Arbitration, 7. The Sovereign Vault, 8. Conclusion. Format the output strictly as valid JSX/React HTML suitable to be injected directly inside a Tailwind CSS container. Use h2 for section headers, h3 for sub-headers, p for paragraphs, and blockquotes for emphasis. Just output the raw HTML tags.";

  console.log("Generating research paper using Gemini Pro...");

  try {
    const result = await model.generateContent(prompt);
    const response = await result.response;
    let htmlContent = response.text();

    // Clean up potential markdown formatting
    htmlContent = htmlContent.replace(/^```(jsx|html|xml)?\n/, '').replace(/\n```$/, '');

    const componentContent = `// Automatically generated by Gemini Pro
export default function ResearchPaperContent() {
  return (
    <>
      ${htmlContent}
    </>
  );
}
`;

    const outputPath = path.join(__dirname, '../src/components/ResearchPaperContent.tsx');
    fs.writeFileSync(outputPath, componentContent, 'utf-8');

    console.log("✅ Successfully generated deep research paper!");

  } catch (error) {
    console.error("❌ Failed to generate paper:", error.message);
  }
}

generatePaper();
